css:
/* Margin halaman PDF 0 (dibaca Frappe dari .print-format); desain punya padding sendiri. */
.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0 !important; }
.print-format, .print-format .ski { background: #f4f1ea; }
.ski { font-family: "SKI Sans", "Liberation Sans", sans-serif; color: #1b1f1e; font-size: 9.5pt; line-height: 1.45; position: relative;
	min-height: 1118px; padding-bottom: 40px; box-sizing: border-box; }
/* Footer menempel di dasar halaman A4 (1123px @96dpi); latar krem penuh saat dicetak / PDF. */
.ski-kaki-blok { position: absolute; left: 0; right: 0; bottom: 0; }
@media print { html, body { background: #f4f1ea !important; } }
.ski table { width: 100%; border-collapse: separate; border-spacing: 0; }
.ski td, .ski th { vertical-align: top; padding: 0; border-left: 0 !important; border-right: 0 !important; border-top: 0; }
.ski-bar { height: 8px; background: #1b1f1e; border-bottom: 4px solid #b5441f; }
.ski-isi { padding: 28px 52px 18px; position: relative; }
.ski-mono { white-space: nowrap; font-family: "SKI Mono", "Liberation Mono", monospace; }
.ski-r { text-align: right; }
.ski-redup { color: #8a8d88; }
.ski-tebal { font-weight: 500; }
.ski-kecil { color: #6b6f6a; font-size: 8.5pt; line-height: 1.5; }
.ski-teks { font-size: 9pt; margin-bottom: 2px; }
.ski-label { font-size: 7.5pt; letter-spacing: 2px; color: #6b6f6a; margin-bottom: 6px; }

.ski-cap { position: absolute; top: 34px; left: 50%; margin-left: -60px; width: 120px; text-align: center; border: 2px solid #b5441f;
	color: #b5441f; font-family: "SKI Condensed", sans-serif; font-weight: 700; letter-spacing: 3px; font-size: 13pt; padding: 2px 0; }
.ski-company { font-family: "SKI Condensed", "Liberation Sans Narrow", sans-serif; font-weight: 700; font-size: 19pt; letter-spacing: 0.5px; margin-bottom: 6px; line-height: 1.1; }
.ski-kanan { text-align: right; }
.ski-judul { font-family: "SKI Condensed", "Liberation Sans Narrow", sans-serif; font-weight: 700; font-size: 44pt; line-height: 0.95; letter-spacing: 1px; }
.ski-nomor { font-family: "SKI Mono", monospace; color: #b5441f; font-size: 10pt; margin-top: 8px; }
.ski-sub { font-size: 7.5pt; letter-spacing: 2px; color: #6b6f6a; margin-top: 4px; }
.ski-garis { border-top: 2px solid #1b1f1e; border-bottom: 1px solid #1b1f1e; height: 2px; margin: 18px 0 18px; }
.ski-garis-tipis { border-top: 1px solid #d8d3c8; margin: 16px 0 14px; }

.ski-tagih { width: 52%; padding-right: 30px !important; }
.ski-customer { font-family: "SKI Condensed", "Liberation Sans Narrow", sans-serif; font-weight: 600; font-size: 17pt; margin-bottom: 6px; line-height: 1.15; }
.ski-meta td { padding: 6px 0 !important; border-bottom: 1px solid #ddd8cc; font-size: 9pt; }
.ski-meta td:first-child { color: #6b6f6a; }
.ski-meta td:last-child { text-align: right; }

.ski-item { table-layout: fixed; }
.ski-item-kepala { background: #1b1f1e; margin-top: 20px; }
.ski-item th { background: transparent; color: #f4f1ea; font-weight: 400; font-size: 7.5pt; letter-spacing: 2px; padding: 10px 8px !important; text-align: left; }
.ski-item th.ski-r { text-align: right; }
.ski-item td { padding: 11px 8px !important; border-bottom: 1px solid #ddd8cc; font-size: 9.5pt; }
.ski-no { width: 42px; padding-left: 16px !important; }
.ski-qty { width: 78px; }
.ski-uang { width: 146px; }
.ski-nama { font-weight: 600; font-size: 10pt; }
.ski-uraian { color: #6b6f6a; font-size: 8pt; margin-top: 2px; }

.ski-ringkas-luar { margin-top: 12px; }
.ski-kosong { width: 40%; }
.ski-ringkas td { padding: 7px 16px !important; border-bottom: 1px solid #ddd8cc; font-size: 9pt; color: #4a4e49; }
.ski-ringkas td.ski-r { color: #1b1f1e; }
.ski-ringkas tr.ski-akhir td { border-bottom: 1px solid #1b1f1e; }
.ski-catatan-kecil { font-size: 7.5pt; color: #8a8d88; }
.ski-total-blok { background: #b5441f; margin-top: 10px; }
.ski-total td { background: transparent; color: #fff; padding: 14px 16px !important; font-family: "SKI Condensed", sans-serif; font-weight: 700;
	font-size: 13pt; letter-spacing: 1.5px; vertical-align: middle; }
.ski-total td { white-space: nowrap; }
.ski-total td.ski-r { font-family: "SKI Mono", monospace; font-weight: 500; font-size: 13pt; letter-spacing: 0; }
.ski-retensi { margin-top: 6px; }
.ski-retensi td { border-bottom: 1px dashed #ddd8cc; }

.ski-terbilang { font-family: "SKI Condensed", "Liberation Sans Narrow", sans-serif; font-style: italic; font-weight: 500; font-size: 13pt; margin-top: 2px; }
.ski-bawah td { width: 50%; padding-right: 24px !important; }
.ski-ttd { margin-top: 12px; }
.ski-ttd-sel { width: 40%; text-align: center; }
.ski-ttd-ruang { height: 42px; }
.ski-ttd-garis { border-top: 1px solid #1b1f1e; }
.ski-ttd-nama { font-weight: 600; font-size: 9pt; margin-top: 6px; }

.ski-kaki-blok { background: #1b1f1e; }
.ski-kaki td { background: transparent; color: #b9bcb6; font-size: 7.5pt; letter-spacing: 2px; padding: 12px 56px !important; font-family: "SKI Mono", monospace; }
/* Bukti Penerimaan Pembayaran */
.ski-judul-panjang { font-size: 30pt; line-height: 1.02; letter-spacing: 0.5px; }
.skp-jumlah { margin-top: 22px; border: 1px solid #6b6f6a !important; border-collapse: collapse !important; }
.skp-jumlah-isi { padding: 16px 22px !important; vertical-align: middle !important; }
.skp-angka { font-family: "SKI Mono", monospace; font-weight: 500; font-size: 22pt; line-height: 1.2; margin: 2px 0 8px; white-space: nowrap; }
.skp-terbilang { font-family: "SKI Condensed", "Liberation Sans Narrow", sans-serif; font-style: italic; font-weight: 500; font-size: 11.5pt; }
.skp-status { width: 168px; background: #b5441f; color: #fff; text-align: center; vertical-align: middle !important; padding: 12px 8px !important; }
.skp-status-teks { font-family: "SKI Condensed", sans-serif; font-weight: 700; font-size: 26pt; letter-spacing: 5px; line-height: 1.1; }
.skp-status, .skp-status div { color: #fff !important; }
.skp-status-sisa { font-size: 7pt; letter-spacing: 1.5px; margin-top: 2px; }
.skp-tgl { width: 112px; }
.ski-item th { white-space: nowrap; }
.skp-uang { width: 118px; }
.skp-sisa { width: 92px; padding-right: 16px !important; }
.ski-item th:first-child, .ski-item td:first-child { padding-left: 16px !important; }
.skp-nomor { font-size: 9.5pt; }
.skp-total td { font-weight: 600; color: #1b1f1e !important; border-bottom: 1px solid #1b1f1e !important; }
.skp-ttd { margin-top: 18px; }
.skp-ttd td { width: 36%; text-align: center; }
.skp-ttd td.skp-ttd-jarak { width: 28%; }
